export function starshieldSvg(lang,kind,mobile=false){
 if(typeof lang!=='string'||!['fr','en'].includes(lang)||typeof kind!=='string'||!STARSHIELD_KINDS.includes(kind)||typeof mobile!=='boolean')throw new TypeError('Invalid Starshield figure variant');
 return FIGURES[`${kind}-${lang}-${mobile?'mobile':'desktop'}`];
}
